import{_ as a,o as e,c as o,a2 as l}from"./chunks/framework.Bqa2y7hU.js";const b=JSON.parse('{"title":"插件市场与安装","description":"浏览插件市场、把插件装到某台机器人、启用停用与配额限制。","frontmatter":{"title":"插件市场与安装","description":"浏览插件市场、把插件装到某台机器人、启用停用与配额限制。"},"headers":[],"relativePath":"console/plugins.md","filePath":"console/plugins.md","lastUpdated":1789230162000}'),r={name:"console/plugins.md"};function i(d,t,n,s,h,c){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="插件市场与安装-🧩" tabindex="-1">插件市场与安装 🧩 <a class="header-anchor" href="#插件市场与安装-🧩" aria-label="Permalink to &quot;插件市场与安装 🧩&quot;">​</a></h1><p>插件是给机器人加功能的唯一方式。控制台里的「插件市场」负责<strong>浏览和安装</strong>，「我的机器人 → 插件 Tab」负责<strong>启停和调优先级</strong>。</p><p>这页把「看到一个插件」到「它真的在机器人上跑起来」这条链路讲完，顺带说清配额限制。</p><h2 id="_1-浏览市场" tabindex="-1">1. 浏览市场 <a class="header-anchor" href="#_1-浏览市场" aria-label="Permalink to &quot;1. 浏览市场&quot;">​</a></h2><p>进「插件市场」，列表里每个插件会显示：</p><table tabindex="0"><thead><tr><th>显示项</th><th>说明</th></tr></thead><tbody><tr><td>插件名称与简介</td><td>这个插件是干什么的</td></tr><tr><td>已安装机器人数</td><td>有多少台机器人装了它，可以当作热度参考</td></tr><tr><td>版本</td><td>当前上架的版本</td></tr></tbody></table><p>点任意一项进入插件详情页，能看到更完整的介绍、支持的平台以及安装入口。</p><details class="details custom-block"><summary>截图占位</summary><p>截插件市场列表页，重点露出「已安装机器人数」这一列的数值。</p></details><h2 id="_2-把插件装到机器人上" tabindex="-1">2. 把插件装到机器人上 <a class="header-anchor" href="#_2-把插件装到机器人上" aria-label="Permalink to &quot;2. 把插件装到机器人上&quot;">​</a></h2><p>在插件详情页点安装，选择要装到<strong>哪一台机器人</strong>。注意插件是按机器人安装的：</p><ul><li>你有三台机器人，想都装上同一个插件，就要装三次</li><li>每台机器人上的同名插件是<strong>独立的一份</strong>，配置互不影响</li></ul><p>装完之后：</p><ol><li>回到「我的机器人」，进目标机器人详情页</li><li>打开「插件」Tab，确认新插件出现在列表里</li><li>处于<strong>启用</strong>状态</li></ol><div class="warning custom-block"><p class="custom-block-title">装上了不等于在跑</p><p>安装只是把插件放到这台机器人上。没启用的话它不会响应任何事件。机器人「没反应」时，先确认这一步。</p></div><h2 id="_3-启用、停用与优先级" tabindex="-1">3. 启用、停用与优先级 <a class="header-anchor" href="#_3-启用、停用与优先级" aria-label="Permalink to &quot;3. 启用、停用与优先级&quot;">​</a></h2><p>在机器人详情页的「插件」Tab 可以：</p><table tabindex="0"><thead><tr><th>操作</th><th>作用</th></tr></thead><tbody><tr><td>启用 / 停用</td><td>单独控制这个插件在这台机器人上跑不跑，不影响其他机器人</td></tr><tr><td>调整优先级</td><td>决定插件的执行顺序，值越小越先执行</td></tr><tr><td>三个拦截开关</td><td><code>Incoming 拦截</code>（消息进来先过这个插件）/ <code>Outgoing 拦截</code>（发出去的消息先过一遍）/ <code>AfterSend 回调</code>（发出后通知插件），机制见 <a href="/RuaBot.Doc/plugin-dev/interceptors">拦截器</a></td></tr><tr><td>进入插件面板</td><td>打开插件自带的 Web 面板做配置</td></tr></tbody></table><p>优先级在多个插件都会处理同一条消息时才需要动：谁先拿到消息、谁能拦截后续处理，都由优先级决定。</p><h2 id="_4-打开插件自带的-web-面板" tabindex="-1">4. 打开插件自带的 Web 面板 <a class="header-anchor" href="#_4-打开插件自带的-web-面板" aria-label="Permalink to &quot;4. 打开插件自带的 Web 面板&quot;">​</a></h2><p>不少插件自带一个独立的 Web 面板，用来做它自己的配置——比如填 API 地址、选触发词、开关子功能。</p><ul><li>入口在机器人详情页的「插件」Tab，点「进入插件面板」</li><li>面板是<strong>插件自带的独立页面</strong>，长什么样由插件作者决定</li><li>面板里的配置存在<strong>机器人维度</strong>：同一插件装在两台机器人上，两边的面板配置是分开的</li></ul><p>插件作者想给自己的插件加面板，见 <a href="/RuaBot.Doc/plugin-dev/webui">插件 Web 面板</a>。</p><h2 id="_5-配额" tabindex="-1">5. 配额 <a class="header-anchor" href="#_5-配额" aria-label="Permalink to &quot;5. 配额&quot;">​</a></h2><p>新建机器人与安装插件都受套餐配额限制，新账号的免费额度是：</p><table tabindex="0"><thead><tr><th>项目</th><th>免费额度</th></tr></thead><tbody><tr><td>机器人位</td><td>1 个</td></tr><tr><td>插件位</td><td>5 个</td></tr></tbody></table><p><strong>插件位是按「装了多少份」算的</strong>——同一个插件装到三台机器人上，占三个插件位。</p><p>超出额度时再装插件会失败，并提示 <code>plugin_quota_exceeded</code>。两种处理方式：</p><ol><li><strong>卸载不用的插件</strong>：在对应机器人的「插件」Tab 里卸载，释放插件位</li><li><strong>升级套餐</strong>：套餐决定机器人位与插件位，见 <a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a></li></ol><div class="tip custom-block"><p class="custom-block-title">卸载前先想清楚</p><p>卸载会一并移除这个插件在这台机器人上的配置与数据。只是暂时不用的话，<strong>停用</strong>就够了。</p></div><h2 id="_6-常见问题" tabindex="-1">6. 常见问题 <a class="header-anchor" href="#_6-常见问题" aria-label="Permalink to &quot;6. 常见问题&quot;">​</a></h2><h3 id="症状-安装时报-plugin-quota-exceeded" tabindex="-1">症状：安装时报 <code>plugin_quota_exceeded</code> <a class="header-anchor" href="#症状-安装时报-plugin-quota-exceeded" aria-label="Permalink to &quot;症状：安装时报 `plugin_quota_exceeded`&quot;">​</a></h3><ul><li><strong>原因</strong>：插件位用满了。</li><li><strong>处理方式</strong>：卸载不用的插件，或升级套餐。</li></ul><h3 id="症状-插件装了也启用了-但机器人不响应" tabindex="-1">症状：插件装了也启用了，但机器人不响应 <a class="header-anchor" href="#症状-插件装了也启用了-但机器人不响应" aria-label="Permalink to &quot;症状：插件装了也启用了，但机器人不响应&quot;">​</a></h3><ul><li><strong>原因</strong>：插件自身没配置（比如缺 API Key、缺触发词），或者被更高优先级的插件拦截了。</li><li><strong>处理方式</strong>：先打开插件面板补全配置；再检查是否有其他插件拦截了消息，必要时调整优先级顺序。</li></ul><h3 id="症状-插件面板打不开" tabindex="-1">症状：插件面板打不开 <a class="header-anchor" href="#症状-插件面板打不开" aria-label="Permalink to &quot;症状：插件面板打不开&quot;">​</a></h3><ul><li><strong>原因</strong>：这个插件本身没有提供 Web 面板。</li><li><strong>处理方式</strong>：面板是可选能力，没有面板的插件按插件详情页里的说明配置即可。</li></ul><h3 id="症状-换了台机器人-插件配置是空的" tabindex="-1">症状：换了台机器人，插件配置是空的 <a class="header-anchor" href="#症状-换了台机器人-插件配置是空的" aria-label="Permalink to &quot;症状：换了台机器人，插件配置是空的&quot;">​</a></h3><ul><li><strong>原因</strong>：这是预期行为，插件配置按机器人维度存储。</li><li><strong>处理方式</strong>：在新机器人的插件面板里重新配置一遍。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/console/bots">我的机器人</a></li><li><a href="/RuaBot.Doc/plugin-dev/webui">插件 Web 面板</a></li><li><a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a></li></ul>',40)])])}const p=a(r,[["render",i]]);export{b as __pageData,p as default};
